function finRoadStrings(){if(!FIN)return [];return FIN.S.filter(s=>{let z0=1e9,z1=-1e9;for(const p of s.pts){z0=Math.min(z0,p[2]);z1=Math.max(z1,p[2]);}return z1-z0>0.3&&s.pts.length>1;});}
function joinRoads(B){const j=B.filter(b=>isFinite(b.join));if(!j.length||!FIN)return [];const zj=Math.min(...j.map(b=>b.join)),top=B[B.length-1];const rings=top.crest.filter(r=>cArea(r)>0).map(ringOf);const out=[];
 for(const s of finRoadStrings()){let cur=[];for(const p of s.pts){const ok=p[2]>=zj-0.05&&p[2]<=top.zc+0.05&&rings.some(r=>inPoly([p[0],p[1]],r));if(ok)cur.push(p.slice());else{if(cur.length>1)out.push({t:'road',z:cur[0][2],pts:cur});cur=[];}}if(cur.length>1)out.push({t:'road',z:cur[0][2],pts:cur});}
 return out;}

/* ---------- proyeksi bench dari batas topo (atas → bawah) ---------- */
function projDist(D,p){if(D<=0)return 0;const n=D/p.H;return n*p.a+Math.floor(n/Math.max(1,p.N)+1e-6)*p.B;}
function makeProj(src3){/* src3: [[E,N,Z]] titik batas mengikuti topo. Proyeksi = batas − pita offset bulat sepanjang batas; lebar pita = jarak horizontal lereng dari elevasi topo titik itu ke RL z (dikelompokkan per 0.5 m agar cepat) */let zmx=-1e9;for(const p of src3)if(isFinite(p[2]))zmx=Math.max(zmx,p[2]);/* titik di luar data topo: dianggap setinggi titik tertinggi (dinding mulai dari atas, tidak tegak sampai dasar) */const ring=densify(src3.concat([src3[0]]),1.5).map(p=>{const t=topoZ(p[0],p[1]);return [p[0],p[1],isFinite(t)?t:zmx];});const Bp=cClean(ClipperLib.Clipper.SimplifyPolygons([toC(src3)],ClipperLib.PolyFillType.pftNonZero));const cache=new Map(),st=0.5;
 if(window.__BOXY&&window.__FLATREF!==0){/* runcing: semua dinding diproyeksikan dari satu RL acuan (titik batas tertinggi) → garis bench lurus dan sejajar seperti string desain staging; bagian di atas topografi hanya udara */return z=>{const k=Math.round(z*100);if(cache.has(k))return cache.get(k);const p=prmAt(z),dd=projDist(zmx-z,p),k0=CORNER;CORNER='miter';let S=dd>0.05?cOff(Bp,-dd):Bp;CORNER=k0;S=cClean(S,2);cache.set(k,S);return S;};}
 return z=>{const k=Math.round(z*100);if(cache.has(k))return cache.get(k);const p=prmAt(z),rr=ring.map(q=>projDist(q[2]-z,p));const grp=new Map();let cur=null,cb=null;
  for(let i=1;i<ring.length;i++){const r=Math.min(rr[i-1],rr[i]);if(r<=0.05){cur=null;continue;}const b=Math.floor(r/st);if(cur&&cb===b&&cur.length<60)cur.push(ring[i]);else{/* polyline dipotong pendek: polyline yang menutup sendiri (batas seluruhnya di atas RL) membuat offset terbalik → irisan kosong */cur=[ring[i-1],ring[i]];cb=b;if(!grp.has(b))grp.set(b,[]);grp.get(b).push(cur);}}
  const U=[];for(const [b,L] of grp){const co=new ClipperLib.ClipperOffset(2,0.1*CS);co.AddPaths(L.map(l=>l.map(q=>({X:Math.round((q[0]-O[0])*CS),Y:Math.round((q[1]-O[1])*CS)}))),JT.jtRound,ET.etOpenRound);const out=new ClipperLib.Paths();co.Execute(out,Math.max(b*st,st*0.5)*CS);for(const q of out)U.push(q);}
  /* selisih langsung (tanpa union antara): union cincin pita kehilangan lubangnya oleh cClean → irisan kosong */let S=U.length?cDiff(Bp,orientAll(U)):Bp;S=tidy(S);cache.set(k,S);return S;};}
function topoStart(){/* RL teratas = kelipatan tinggi bench di bawah elevasi tertinggi batas */const src=BASE.src3||BASE.src.map(p=>[p[0],p[1],topoZ(p[0],p[1])]);let zmx=-1e9;for(const p of src)if(isFinite(p[2]))zmx=Math.max(zmx,p[2]);const H=PN().H,zr=isFinite(BASE.z)?BASE.z:0;
 let z=zr+Math.floor((zmx-zr)/H)*H;/* RL atas galian: bench teratas tidak lebih tinggi dari isian user */const zA=typeof aTop==='function'?aTop(BASE):NaN;if(isFinite(zA)&&zA<z)z=zr+Math.floor((zA-zr)/H+1e-6)*H;const proj=makeProj(src.map(p=>[p[0],p[1],isFinite(p[2])?p[2]:zmx]));let C=proj(z),g=0;while((!C.length||C.reduce((s,r)=>s+Math.max(0,cArea(r)),0)<50)&&g++<60){z-=H;C=proj(z);}return {z,C,proj};}

