 if(i<0)return null;const fa=B[i].fa,rp=RAMP();let q=[fa.hi[0],fa.hi[1]],v=fa.dirv?[-fa.dirv[0],-fa.dirv[1]]:null,zq=fa.hi[2],entry=null,ent=null,path=[[q[0],q[1],zq]];
 for(let k=i-1;k>=-1;k--){const P=k>=0?B[k].crest:ts.C,zc=k>=0?B[k].zc:ts.z,H=k>=0?B[k].zc-B[k].zt:prmAt(ts.z).H;if(k<0)break;const Pi=cOff(P,-(prmAt(zc).H/Math.tan(Math.min(prmAt(zc).A,88.9)*Math.PI/180)/2+rp.W/2)).filter(r=>cArea(r)>0);/* lintasan pusat jalan ± di dalam crest */const R=ringFor(Pi.length?Pi:P,q);if(!R)break;
  let sgn=1;if(v){const t=tanAt(R.r,R.c,R.n.s,4);sgn=(t[0]*v[0]+t[1]*v[1])>=0?1:-1;}const L=H/rp.g;const A=ringAt(R.r,R.c,R.n.s+sgn*L).p,tz=topoZ(A[0],A[1]);
  if(TP.length&&isFinite(tz)&&tz<zc-0.3){/* titik berikutnya sudah di udara → pintu masuk di bench ini */entry=[q[0],q[1]];break;}
  const t2=tanAt(R.r,R.c,R.n.s+sgn*L,4);v=[t2[0]*sgn,t2[1]*sgn];q=[A[0],A[1]];zq=zc;path.push([q[0],q[1],zc]);entry=[q[0],q[1]];ent={zc,dv:[-v[0],-v[1]],P};}
